public class Program_SumofEvenNumber {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
				        int sum = 0;

		        // Loop from 1 to 50
		        for (int i = 1; i <= 50; i++) {
		            // Check if the number is even
		            if (i % 2 == 0) {
		                sum += i; // Add even number to sum
		            }
		        }

		        // Display the result
		          System.out.println("Sum of even numbers = " + sum);
		    }
		


	}


